use alloc::{boxed::Box, string::String};
use bevy_platform::{
    collections::HashMap,
    hash::NoOpHash,
    sync::{PoisonError, RwLock},
};
use core::{
    any::TypeId,
    fmt::{Debug, Display},
    ops::{Deref, Range},
};

/// A standardized, stable Rust type path, intended to be usable as a "canonical" name for a type.
///
/// The engine uses this over [`core::any::type_name`] for stability and flexibility.
///
/// This is automatically generated by the `#[derive(Reflect)]` macro
/// and allows type path information to be processed without an instance of that type.
///
/// This is intended to be constructed by derives and proc macros in this crate, as populating the
/// ranges for each part of the path can be challenging.
///
/// This uses a condensed representation to avoid storing multiple strings in the output binary.
///
/// Paths of non-generic types are known at compile time and can be read in `const` contexts using
/// the `try_*` methods (ex: [`TypePath::try_full`]).
///
/// # Stability
///
/// Certain parts of the engine, e.g. [(de)serialization], rely on type paths as identifiers
/// for matching dynamic values to concrete types.
///
/// Using [`core::any::type_name`], a scene containing `my_crate::foo::MyComponent` would break,
/// failing to deserialize if the component was moved from the `foo` module to the `bar` module,
/// becoming `my_crate::bar::MyComponent`.
/// [`TypePath`], through configuration in [`Reflect`](crate::Reflect), can ensure breaking changes are avoidable.
pub struct TypePath {
    full: TypePathStr,
    short: TypePathStr,
    type_ident: Range<usize>,
    crate_name: Option<Range<usize>>,
    module_path: Option<Range<usize>>,
}

/// A type path string, which is either known at compile time or computed lazily at runtime.
#[derive(Clone, Copy)]
pub enum TypePathStr {
    /// A path known at compile time. Used by non-generic types.
    Static(&'static str),
    /// A path computed at runtime. Used by generic types, whose paths depend on their generic parameters.
    Lazy(fn() -> &'static str),
}

impl TypePathStr {
    /// Returns the path.
    pub fn get(self) -> &'static str {
        match self {
            TypePathStr::Static(value) => value,
            TypePathStr::Lazy(f) => f(),
        }
    }

    /// Returns the path if it is [`TypePathStr::Static`].
    pub const fn get_static(self) -> Option<&'static str> {
        match self {
            TypePathStr::Static(value) => Some(value),
            TypePathStr::Lazy(_) => None,
        }
    }
}

impl Debug for TypePath {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.full())
    }
}

impl Display for TypePath {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.short())
    }
}

impl Deref for TypePath {
    type Target = str;

    fn deref(&self) -> &Self::Target {
        self.full()
    }
}
impl TypePath {
    /// Creates a new instance of [`TypePath`]. Getting the ranges right is tricky, and this is
    /// generally called by macros.
    pub const fn new(
        full: TypePathStr,
        short: TypePathStr,
        type_ident: Range<usize>,
        crate_name: Option<Range<usize>>,
        module_path: Option<Range<usize>>,
    ) -> Self {
        Self {
            full,
            short,
            type_ident,
            crate_name,
            module_path,
        }
    }

    /// Creates the path of a generic type `T` named `type_ident`, defined in the module at
    /// `module_path` (which starts with the crate name). The path strings are computed by `T`'s
    /// [`GenericTypePath`] implementation.
    pub const fn generic<T: GenericTypePath>(
        module_path: &'static str,
        type_ident: &'static str,
    ) -> Self {
        let crate_len = match find_ascii_char(module_path, b':') {
            Some(value) => value,
            None => module_path.len(),
        };
        Self::new(
            TypePathStr::Lazy(T::type_path),
            TypePathStr::Lazy(T::short_type_path),
            0..type_ident.len(),
            Some(0..crate_len),
            Some(0..module_path.len()),
        )
    }

    /// Returns the full type path. This includes the full module/crate path, including for generic types.
    /// This is intended to be usable as a roughly "unique" identifier, provided there are no crate name overlaps.
    ///
    /// For `Option<Vec<usize>>`, this is `"core::option::Option<alloc::vec::Vec<usize>>"`.
    ///
    /// See [`Self::short`] for short / "friendly" names.
    pub fn full(&self) -> &'static str {
        self.full.get()
    }

    /// Returns the full type pat. This includes the full module/crate path, including for generic types.
    /// This is intended to be usable as a roughly "unique" identifier, provided there are no crate name overlaps.
    /// For example: `String`, `Player`, `Vec<Item>`
    pub fn short(&self) -> &'static str {
        self.short.get()
    }

    /// Returns the name of the type
    ///
    /// For `Option<Vec<usize>>`, this is `"Option"`.
    pub fn type_ident(&self) -> &'static str {
        const_index(self.short(), &self.type_ident)
    }

    /// Returns the name of the crate the type is in, or [`None`] if it has no crate name.
    ///
    /// For `Option<Vec<usize>>`, this is `"core"`.
    pub fn crate_name(&self) -> Option<&'static str> {
        match &self.crate_name {
            Some(range) => Some(const_index(self.full(), range)),
            None => None,
        }
    }

    /// Returns the path to the module the type is in, or [`None`] if it has no module path.
    ///
    /// For `Option<Vec<usize>>`, this is `"core::option"`.
    pub fn module_path(&self) -> Option<&'static str> {
        match &self.module_path {
            Some(range) => Some(const_index(self.full(), range)),
            None => None,
        }
    }

    /// Returns [`TypePath::full`] if it is known at compile time (ex: the type is not generic).
    pub const fn try_full(&self) -> Option<&'static str> {
        self.full.get_static()
    }

    /// Returns [`TypePath::short`] if it is known at compile time (ex: the type is not generic).
    pub const fn try_short(&self) -> Option<&'static str> {
        self.short.get_static()
    }

    /// Returns [`TypePath::type_ident`] if it is known at compile time (ex: the type is not generic).
    pub const fn try_type_ident(&self) -> Option<&'static str> {
        match self.try_short() {
            Some(short) => Some(const_index(short, &self.type_ident)),
            None => None,
        }
    }

    /// Returns [`TypePath::crate_name`] if it is known at compile time (ex: the type is not generic).
    pub const fn try_crate_name(&self) -> Option<Option<&'static str>> {
        match self.try_full() {
            Some(full) => Some(match &self.crate_name {
                Some(range) => Some(const_index(full, range)),
                None => None,
            }),
            None => None,
        }
    }

    /// Returns [`TypePath::module_path`] if it is known at compile time (ex: the type is not generic).
    pub const fn try_module_path(&self) -> Option<Option<&'static str>> {
        match self.try_full() {
            Some(full) => Some(match &self.module_path {
                Some(range) => Some(const_index(full, range)),
                None => None,
            }),
            None => None,
        }
    }
}

const fn const_index<'a>(s: &'a str, range: &Range<usize>) -> &'a str {
    s.split_at(range.start)
        .1
        .split_at(range.end - range.start)
        .0
}

/// Concatenates the bytes of an array of strings in a const context, returning a combined array of
/// bytes. The final size of the output bytes must be known at compile time and passed as the const `N`.
/// This is used by [`const_concat`].
pub const fn concat_many<const N: usize>(values: &[&str]) -> [u8; N] {
    let mut total_len = 0;
    let mut i = 0;
    while i < values.len() {
        total_len += values[i].len();
        i += 1;
    }
    assert!(total_len == N);
    let mut out = [0u8; N];
    let mut i = 0;
    let mut offset = 0;
    while i < values.len() {
        let string_as_bytes = values[i].as_bytes();
        let mut byte_index = 0;
        while byte_index < string_as_bytes.len() {
            out[offset + byte_index] = string_as_bytes[byte_index];
            byte_index += 1;
        }
        offset += string_as_bytes.len();
        i += 1;
    }
    out
}

#[doc(hidden)]
#[macro_export]
macro_rules! sum {
    ($first:expr $(, $rest:expr)* $(,)?) => { $first $(+ $rest)* };
}

/// Concatenates `const` string expressions into a `&'static str`.
#[macro_export]
macro_rules! const_concat {
    ($($value:expr),*) => {{
        // Stored in a `const` so that `&BYTES` is promoted to `'static`. A temporary would be
        // dropped too early when this macro is used in some positions (ex: as a function argument).
        const BYTES: [u8; $crate::sum!($($value.len()),*)] = $crate::concat_many(&[$($value),*]);
        match ::core::str::from_utf8(&BYTES) {
            Ok(value) => value,
            Err(_) => panic!("Output bytes are not valid utf8"),
        }
    }};
}

/// Finds the byte index of the first instance of the ascii character `delimiter` in the given `s` string.
/// This is used by [`const_concat`].
pub const fn find_ascii_char(s: &str, delimiter: u8) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() {
        if bytes[i] == delimiter {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// Lazily computes the type path of a generic type.
///
/// This is only implemented for generic types, whose [`TypePath`] uses [`TypePathStr::Lazy`] to point to
/// these functions. Use [`Typed::TYPE`](crate::Typed::TYPE) to get the type path of any type.
pub trait GenericTypePath {
    /// The full type path.
    fn type_path() -> &'static str;
    /// The short type path.
    fn short_type_path() -> &'static str;
}

/// Lazily stores a type path string per [`TypeId`].
pub struct GenericTypePathCell(RwLock<HashMap<TypeId, &'static str, NoOpHash>>);

impl GenericTypePathCell {
    /// Creates a new empty [`GenericTypePathCell`].
    pub const fn new() -> Self {
        Self(RwLock::new(HashMap::with_hasher(NoOpHash)))
    }

    /// Returns the path stored for `type_id`, initializing it with `f` if it does not exist yet.
    pub fn get_or_insert(&self, type_id: TypeId, f: impl FnOnce() -> String) -> &'static str {
        if let Some(path) = self
            .0
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .get(&type_id)
        {
            return path;
        }
        let path = f();
        self.0
            .write()
            .unwrap_or_else(PoisonError::into_inner)
            .entry(type_id)
            // Leaked to obtain a `&'static str`. Each type is only initialized once.
            .or_insert_with(|| Box::leak(path.into_boxed_str()))
    }
}

impl Default for GenericTypePathCell {
    fn default() -> Self {
        Self::new()
    }
}

/// Implements [`GenericTypePath`](crate::GenericTypePath) for a type whose path is
/// `$module::$ident<$($param),*>`.
macro_rules! impl_generic_type_path {
    (impl<$($param:ident),*> for $ty:ty, $module:literal, $ident:literal $(, where $($bounds:tt)*)?) => {
        impl<$($param),*> $crate::GenericTypePath for $ty
        where
            $($param: $crate::Typed,)*
            $($($bounds)*)?
        {
            fn type_path() -> &'static str {
                static CELL: $crate::GenericTypePathCell = $crate::GenericTypePathCell::new();
                CELL.get_or_insert(::core::any::TypeId::of::<Self>(), || {
                    let params: &[&str] = &[$(<$param as $crate::Typed>::TYPE.type_path().full()),*];
                    $crate::__macro_exports::format!("{}::{}<{}>", $module, $ident, params.join(", "))
                })
            }

            fn short_type_path() -> &'static str {
                static CELL: $crate::GenericTypePathCell = $crate::GenericTypePathCell::new();
                CELL.get_or_insert(::core::any::TypeId::of::<Self>(), || {
                    let params: &[&str] = &[$(<$param as $crate::Typed>::TYPE.type_path().short()),*];
                    $crate::__macro_exports::format!("{}<{}>", $ident, params.join(", "))
                })
            }
        }
    };
}

pub(crate) use impl_generic_type_path;
